247: fn write_one(archive: &mut Archive, f: &PendingFile) -> Result<()> {
248:     let mut entry = archive
249:         .by_index(f.index)
250:         .map_err(|e| zerr(format!("failed to read entry {}: {e}", f.index)))?;
251:     let out = open_output_file(&f.out_path, f.mode)?;
252:     let buf_cap = f.declared_size.clamp(WRITE_BUF_MIN, WRITE_BUF_MAX) as usize;
253:     let out = BufWriter::with_capacity(buf_cap, out);
254:     // Abort if an entry inflates past its declared size (malformed archive).
255:     let limit = f
256:         .declared_size
257:         .saturating_add(64)
258:         .saturating_mul(2)
259:         .max(1024 * 1024);
260:     let mut w = LimitedWriter {
261:         inner: out,
262:         written: 0,
263:         limit,
264:     };
265:     io::copy(&mut entry, &mut w)
266:         .map_err(|e| zerr(format!("failed to write '{}': {e}", f.out_path.display())))?;
267:     let fh = w
268:         .inner
269:         .into_inner()
270:         .map_err(|e| zerr(format!("failed to flush '{}': {e}", f.out_path.display())))?;
271:     // open(2) applies the process umask to the create mode; fchmod the handle so
272:     // the archive's bits land exactly (matches upstream extract-zip). `f.mode`
273:     // is already & MODE_MASK from pass 1; re-mask here so the setuid strip is
274:     // enforced locally regardless of caller.
275:     #[cfg(unix)]
276:     {
277:         use std::os::unix::fs::PermissionsExt;
278:         let _ = fh.set_permissions(fs::Permissions::from_mode(f.mode & MODE_MASK));
279:     }
280:     if let Some(t) = f.mtime {
281:         // Set via the open handle: no path re-resolution, no symlink follow.
282:         let _ = filetime::set_file_handle_times(&fh, None, Some(t));
283:     }
284:     Ok(())
285: }
