287: /// `io::copy` sink that errors once `limit` bytes have been written.
288: struct LimitedWriter<W: Write> {
289:     inner: W,
290:     written: u64,
291:     limit: u64,
292: }
293: 
294: impl<W: Write> Write for LimitedWriter<W> {
295:     fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
296:         if self.written.saturating_add(buf.len() as u64) > self.limit {
297:             return Err(io::Error::new(
298:                 io::ErrorKind::FileTooLarge,
299:                 format!(
300:                     "uncompressed output exceeded {} bytes (zip bomb?)",
301:                     self.limit
302:                 ),
303:             ));
304:         }
305:         let n = self.inner.write(buf)?;
306:         self.written += n as u64;
307:         Ok(n)
308:     }
309:     fn flush(&mut self) -> io::Result<()> {
310:         self.inner.flush()
311:     }
312: }
