349: /// Ensure `path` exists as a chain of *real* directories beneath `dest_canon`.
350: ///
351: /// Walks the suffix `path - dest_canon` one component at a time and at each
352: /// step `lstat`s the result: a missing component is `mkdir`ed; an existing
353: /// real directory is accepted; **anything else (symlink, file) is rejected**.
354: /// We never `canonicalize` after the fact, so we never create something
355: /// outside `dest` and only then notice. `path` must be a literal descendant of
356: /// `dest_canon` — the caller guarantees this via `enclosed_name()`.
357: fn ensure_dir_nofollow(path: &Path, dest_canon: &Path, cache: &mut HashSet<PathBuf>) -> Result<()> {
358:     if cache.contains(path) {
359:         return Ok(());
360:     }
361:     let suffix = path.strip_prefix(dest_canon).map_err(|_| {
362:         zerr(format!(
363:             "internal: '{}' is not under destination",
364:             path.display()
365:         ))
366:     })?;
367:     let mut cur = dest_canon.to_path_buf();
368:     for c in suffix.components() {
369:         let Component::Normal(name) = c else {
370:             return Err(zerr(format!(
371:                 "internal: unexpected path component in '{}'",
372:                 path.display()
373:             )));
374:         };
375:         cur.push(name);
376:         if cache.contains(&cur) {
377:             continue;
378:         }
379:         match fs::symlink_metadata(&cur) {
380:             Ok(m) if m.is_dir() => {}
381:             Ok(m) if m.file_type().is_symlink() => {
382:                 return Err(zerr(format!(
383:                     "refusing to traverse symlink at '{}'",
384:                     cur.display()
385:                 )));
386:             }
387:             Ok(_) => {
388:                 return Err(zerr(format!(
389:                     "cannot create directory '{}': a file already exists there",
390:                     cur.display()
391:                 )));
392:             }
393:             Err(e) if e.kind() == io::ErrorKind::NotFound => {
394:                 fs::create_dir(&cur).map_err(|e| {
395:                     zerr(format!(
396:                         "failed to create directory '{}': {e}",
397:                         cur.display()
398:                     ))
399:                 })?;
400:             }
401:             Err(e) => {
402:                 return Err(zerr(format!("failed to stat '{}': {e}", cur.display())));
403:             }
404:         }
405:         cache.insert(cur.clone());
406:     }
407:     Ok(())
408: }
