410: fn open_output_file(path: &Path, mode: u32) -> Result<File> {
411:     #[cfg(not(unix))]
412:     let _ = mode;
413:     let mut opts = OpenOptions::new();
414:     opts.write(true).create_new(true);
415:     #[cfg(unix)]
416:     {
417:         use std::os::unix::fs::OpenOptionsExt;
418:         opts.mode(mode);
419:     }
420:     match opts.open(path) {
421:         Ok(f) => Ok(f),
422:         Err(e) if e.kind() == io::ErrorKind::AlreadyExists => {
423:             // Unlink + O_EXCL retry: never open() through a pre-existing symlink.
