1: // Refuses to publish unless every declared target has a prebuilt `.node` in
2: // the package root. The fat package ships all of them; a missing one means a
3: // CI matrix leg failed.
4: 
5: import fs from 'node:fs';
6: import path from 'node:path';
7: import { fileURLToPath } from 'node:url';
8: 
9: // triple → expected .node filename (matches what napi build --platform emits)
10: const EXPECTED = {
11:   'universal-apple-darwin': 'index.darwin-universal.node',
12:   'x86_64-pc-windows-msvc': 'index.win32-x64-msvc.node',
13:   'aarch64-pc-windows-msvc': 'index.win32-arm64-msvc.node',
14:   'x86_64-unknown-linux-gnu': 'index.linux-x64-gnu.node',
15:   'aarch64-unknown-linux-gnu': 'index.linux-arm64-gnu.node',
16:   'x86_64-unknown-linux-musl': 'index.linux-x64-musl.node',
17:   'aarch64-unknown-linux-musl': 'index.linux-arm64-musl.node',
18:   'i686-unknown-linux-gnu': 'index.linux-ia32-gnu.node',
19:   'armv7-unknown-linux-gnueabihf': 'index.linux-arm-gnueabihf.node',
20: };
21: 
22: const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
23: const missing = Object.entries(EXPECTED).filter(
24:   ([, f]) => !fs.existsSync(path.join(dir, f)),
25: );
26: 
27: if (missing.length) {
28:   console.error('Refusing to publish — missing prebuilds:');
29:   for (const [triple, f] of missing) console.error(`  ${triple.padEnd(30)} ${f}`);
30:   process.exit(1);
31: }
32: 
33: let total = 0;
34: for (const f of Object.values(EXPECTED)) {
35:   const { size } = fs.statSync(path.join(dir, f));
36:   total += size;
37:   console.log(`  ${f.padEnd(34)} ${(size / 1024).toFixed(0).padStart(5)} KB`);
38: }
39: console.log(`  ${'total'.padEnd(34)} ${(total / 1024).toFixed(0).padStart(5)} KB`);
40: 
41: // Belt-and-braces: the published binding.js must not contain a require() of an
42: // `@electron-internal/...-<triple>` package — that fallback path is a
43: // dependency-confusion foothold on platforms we don't ship a prebuild for.
44: const binding = fs.readFileSync(path.join(dir, 'binding.js'), 'utf8');
